// ─── PASTE YOUR VERIFY TOKEN HERE ────────────────────────────────────
//     The same string you type into Meta's "Verify token" box.
const META_VERIFY_TOKEN = '';
// ─────────────────────────────────────────────────────────────────────
//
// Meta calls every callback URL once with GET to verify ownership.

const q = $json.query || {};
const token = String(q['hub.verify_token'] || '');

let diff = token.length ^ META_VERIFY_TOKEN.length;
for (let i = 0; i < token.length && i < META_VERIFY_TOKEN.length; i++) {
  diff |= token.charCodeAt(i) ^ META_VERIFY_TOKEN.charCodeAt(i);
}
const ok = Boolean(META_VERIFY_TOKEN) && q['hub.mode'] === 'subscribe' && diff === 0;

return [{ json: { verified: ok, challenge: ok ? String(q['hub.challenge'] || '') : '' } }];

// ─── PASTE YOUR APP SECRET HERE ──────────────────────────────────────
//     Meta app → App settings → Basic → App Secret
const META_APP_SECRET = '';
// ─────────────────────────────────────────────────────────────────────
//
// Meta signs every webhook POST with HMAC-SHA256 over the RAW body.
// n8n's Code sandbox exposes neither require() nor a crypto global, so
// SHA-256 and HMAC are implemented here in plain JavaScript. Verified
// byte-identical to Node's createHmac across block-boundary lengths and
// key sizes. Buffer is available in the sandbox and is used for I/O only.

if (!META_APP_SECRET) throw new Error('META_APP_SECRET is empty - refusing to process an unverified Meta webhook');

const K = new Uint32Array([
  0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
  0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
  0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
  0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
  0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
  0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
  0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
  0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2]);
const rotr = (x, n) => ((x >>> n) | (x << (32 - n))) >>> 0;

function sha256(bytes) {
  const H = new Uint32Array([0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
                             0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19]);
  const l = bytes.length;
  const padded = new Uint8Array(((l + 9) + 63) & ~63);
  padded.set(bytes); padded[l] = 0x80;
  const dv = new DataView(padded.buffer);
  const bits = l * 8;
  dv.setUint32(padded.length - 8, Math.floor(bits / 4294967296));
  dv.setUint32(padded.length - 4, bits >>> 0);
  const w = new Uint32Array(64);
  for (let off = 0; off < padded.length; off += 64) {
    for (let t = 0; t < 16; t++) w[t] = dv.getUint32(off + t * 4);
    for (let t = 16; t < 64; t++) {
      const x = w[t-15], y = w[t-2];
      const s0 = (rotr(x,7) ^ rotr(x,18) ^ (x >>> 3)) >>> 0;
      const s1 = (rotr(y,17) ^ rotr(y,19) ^ (y >>> 10)) >>> 0;
      w[t] = (w[t-16] + s0 + w[t-7] + s1) >>> 0;
    }
    let a=H[0],b=H[1],c=H[2],d=H[3],e=H[4],f=H[5],g=H[6],h=H[7];
    for (let t = 0; t < 64; t++) {
      const S1 = (rotr(e,6) ^ rotr(e,11) ^ rotr(e,25)) >>> 0;
      const ch = ((e & f) ^ (~e & g)) >>> 0;
      const t1 = (h + S1 + ch + K[t] + w[t]) >>> 0;
      const S0 = (rotr(a,2) ^ rotr(a,13) ^ rotr(a,22)) >>> 0;
      const maj = ((a & b) ^ (a & c) ^ (b & c)) >>> 0;
      const t2 = (S0 + maj) >>> 0;
      h=g; g=f; f=e; e=(d+t1)>>>0; d=c; c=b; b=a; a=(t1+t2)>>>0;
    }
    H[0]=(H[0]+a)>>>0; H[1]=(H[1]+b)>>>0; H[2]=(H[2]+c)>>>0; H[3]=(H[3]+d)>>>0;
    H[4]=(H[4]+e)>>>0; H[5]=(H[5]+f)>>>0; H[6]=(H[6]+g)>>>0; H[7]=(H[7]+h)>>>0;
  }
  const out = new Uint8Array(32), odv = new DataView(out.buffer);
  for (let i = 0; i < 8; i++) odv.setUint32(i * 4, H[i]);
  return out;
}

function hmacHex(keyBytes, msgBytes) {
  let k = keyBytes;
  if (k.length > 64) k = sha256(k);
  const key = new Uint8Array(64); key.set(k);
  const ipad = new Uint8Array(64 + msgBytes.length);
  const opad = new Uint8Array(64 + 32);
  for (let i = 0; i < 64; i++) { ipad[i] = key[i] ^ 0x36; opad[i] = key[i] ^ 0x5c; }
  ipad.set(msgBytes, 64);
  opad.set(sha256(ipad), 64);
  let s = '';
  for (const b of sha256(opad)) s += b.toString(16).padStart(2, '0');
  return s;
}

const item = $input.first();
const headers = item.json.headers || {};
const signature = String(headers['x-hub-signature-256'] || '');

const b64 = item.binary && item.binary.data && item.binary.data.data;
if (!b64) throw new Error('Raw body missing - enable the "Raw Body" option on the webhook node');
const raw = Buffer.from(b64, 'base64');

const expected = 'sha256=' + hmacHex(
  new Uint8Array(Buffer.from(META_APP_SECRET, 'utf8')),
  new Uint8Array(raw));

// constant-time compare
let diff = signature.length ^ expected.length;
for (let i = 0; i < signature.length && i < expected.length; i++) {
  diff |= signature.charCodeAt(i) ^ expected.charCodeAt(i);
}
if (diff !== 0) throw new Error('Invalid X-Hub-Signature-256 - rejecting webhook');

return [{ json: { headers, body: JSON.parse(raw.toString('utf8')) } }];

// Turns one Instagram webhook into zero or more guest messages.
//
// Returning [] ends the branch cleanly - that is how non-conversational
// events are dropped. The filtering here is not cosmetic:
//
//   is_echo  - Meta fires a webhook for every message WE send. Without this
//              the agent reads its own reply and answers it, forever.
//   read /
//   delivery - receipts, not messages.
//   deleted  - retraction, nothing to answer.
//   no text  - a like, sticker or bare attachment. The agent has nothing to
//              work with and would invent a reply to nothing.

const b = $json.body || $json;
const entries = Array.isArray(b.entry) ? b.entry : [];
const out = [];

for (const entry of entries) {
  // `messaging` is the DM shape; `changes` appears on other subscriptions.
  const events = Array.isArray(entry.messaging) ? entry.messaging
               : Array.isArray(entry.changes)   ? entry.changes.map(c => c?.value).filter(Boolean)
               : Array.isArray(b.messaging)     ? b.messaging
               : [];

  for (const m of events) {
    if (!m || m.read || m.delivery || m.reaction) continue;

    const msg = m.message || {};
    if (msg.is_echo || msg.is_deleted) continue;

    const text = String(
      msg.text ||
      m.postback?.title ||
      msg.quick_reply?.payload ||
      ''
    ).trim();
    if (!text) continue;

    const senderId = m.sender?.id || '';
    if (!senderId) continue;

    out.push({ json: {
      channel: 'instagram',
      senderId,
      recipientId: m.recipient?.id || '',
      messageId: msg.mid || m.postback?.mid || '',
      text,
      sessionId: `instagram:${senderId}`,
      raw: b,
    }});
  }
}

return out;

// Runs per item: one webhook can carry several DMs.
const j = $json;
const c = {
  channel: j.channel,
  senderId: j.senderId || '',
  recipientId: j.recipientId || '',
  sessionId: j.sessionId || '',
  messageId: j.messageId || '',
  lead: j.lead || null,
  userMessage: String(j.text || '').trim(),
};

return { json: { ...j, agentPrompt: `You are the Bougainvilla Booking AI Agent. Act as sales, concierge and support for Bougainvilla Resorts. Use tools for live data/actions; never invent availability, prices, booking IDs, policies or amenities. Convert qualified enquiries into confirmed bookings. Channel=${j.channel}. Guest context=${JSON.stringify(c)}. Return ONLY valid JSON with keys intent,reply,booking_status,lead_stage,needs_human,property_id,check_in,check_out,guests,booking_id. booking_status=enquiry|availability_checked|awaiting_payment|booked|support|cancelled. For booking: check availability first; create booking only after explicit confirmation and complete required details. Use only payment links returned by tools. Escalate refunds, emergencies, policy exceptions, uncertainty.` } };

// Runs per item so each guest's reply is paired with their own message.
// The model is told to return JSON; when it doesn't, fall back to a
// human-handoff rather than sending the guest raw model output as a booking.
const raw = String($json.output || $json.text || '').trim();

let d;
try { d = JSON.parse(raw); }
catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) { try { d = JSON.parse(m[0]); } catch (_) {} }
}
if (!d) d = {
  intent: 'support',
  reply: raw || 'Sorry, I could not process that request.',
  booking_status: 'support',
  lead_stage: 'needs_human',
  needs_human: true,
};

const o = $('Build Unified Agent Context').item.json;

return { json: {
  ...o, ...d,
  reply: String(d.reply || ''),
  channel: o.channel,
  senderId: o.senderId || '',
  recipientId: o.recipientId || '',
  sessionId: o.sessionId || '',
} };

const x=$input.first().json.body ?? $input.first().json;
return [{json:{
 event:"booking_lead",
 lead_id:x.lead_id||x.id||`lead_${Date.now()}`,
 guest_name:x.guest_name||x.name||"Guest",
 phone:x.phone||null,email:x.email||null,
 check_in:x.check_in||null,check_out:x.check_out||null,
 guests:Number(x.guests||1),budget:x.budget??null,
 message:x.message||"",
 property_id:x.property_id||null,
 source:x.source||"unknown",
 raw:x
}}];

const input=$input.first().json; const p=input.body ?? input;
const lead=$('Normalize Booking Lead').first().json;
return [{json:{lead,pms:p, prompt:`You are a Bougainvilla vacation-rental sales agent. Return STRICT JSON with keys decision,reply,alternative_request. Guest: ${lead.guest_name}. Dates: ${lead.check_in} to ${lead.check_out}. Guests: ${lead.guests}. Budget: ${lead.budget}. Message: ${lead.message}. Availability data: ${JSON.stringify(p)}. If available, be concise and move toward booking. Never invent price or availability. If unavailable, ask for alternative dates or property.`}}];

const r=$input.first().json; let c=r.choices?.[0]?.message?.content||"{}"; let a; try{a=JSON.parse(c)}catch(e){a={decision:"human_review",reply:c,alternative_request:null}};
const lead=$('Normalize Booking Lead').first().json;
return [{json:{ok:true,event:"booking_lead_processed",lead_id:lead.lead_id,guest_phone:lead.phone,decision:a.decision,reply:a.reply,alternative_request:a.alternative_request,requires_human:a.decision==="human_review"}}];

let c=$input.first().json.choices?.[0]?.message?.content||"{}";let a;try{a=JSON.parse(c)}catch(e){a={intent:"unknown",priority:"high",reply:c,needs_human:true}};
const x=$('Normalize Voice Event').first().json;
return [{json:{...x,ai:a,escalate:Boolean(a.needs_human)||a.priority==="urgent"}}];

// Runs per item: each lead keeps its own AI copy.
const src = $('Build Follow-up Messages').item.json;
const text = $json.choices?.[0]?.message?.content;
return { json: { lead_id: src.lead_id, phone: src.phone, message: text || 'Hi! Just checking if you still need help with your stay at Bougainvilla.' } };

// Runs per item: each property keeps its own recommendation.
const src = $('Build Pricing Prompt').item.json;
let a;
try { a = JSON.parse($json.choices?.[0]?.message?.content || '{}'); }
catch (e) { a = { recommended_price: null, reason: 'AI parse failure', confidence: 0, action: 'human_review' }; }
return { json: { property_id: src.property_id, current_price: src.current_price, recommendation: a, requires_approval: true } };

// ─── PASTE YOUR DASHBOARD KEY HERE ───────────────────────────────────
//     Same value as DASHBOARD_API_KEY in the Vercel project.
//     Generate with: openssl rand -hex 32
const DASHBOARD_API_KEY = '';
// ─────────────────────────────────────────────────────────────────────

if (!DASHBOARD_API_KEY) throw new Error('DASHBOARD_API_KEY is empty - refusing to serve metrics');

const got = String(($json.headers || {})['x-api-key'] || '');
let diff = got.length ^ DASHBOARD_API_KEY.length;
for (let i = 0; i < got.length && i < DASHBOARD_API_KEY.length; i++) {
  diff |= got.charCodeAt(i) ^ DASHBOARD_API_KEY.charCodeAt(i);
}
if (diff !== 0) throw new Error('Unauthorized dashboard request');

return [{ json: { authorized: true } }];

// Shapes whatever the CRM returns into the contract the dashboard reads.
// If the CRM is unreachable the dashboard is told so and keeps its demo numbers.
const r = $json || {};
const failed = !!r.error || Object.keys(r).length === 0;
const src = r.data || r;
const num = (v, d = null) => (typeof v === 'number' && isFinite(v) ? v : d);

return [{ json: {
  generated_at: new Date().toISOString(),
  source: failed ? 'unavailable' : 'crm',
  stats: {
    total_bookings: num(src.total_bookings),
    active_leads:   num(src.active_leads),
    revenue_mtd:    num(src.revenue_mtd),
    avg_rating:     num(src.avg_rating)
  },
  channels: {
    instagram: num(src.channels?.instagram),
    direct:    num(src.channels?.direct),
    voice:     num(src.channels?.voice)
  },
  revenue_series: {
    labels: Array.isArray(src.revenue_series?.labels) ? src.revenue_series.labels : null,
    values: Array.isArray(src.revenue_series?.values) ? src.revenue_series.values : null
  },
  recent_bookings: Array.isArray(src.recent_bookings) ? src.recent_bookings.slice(0, 8) : null,
  recent_leads:    Array.isArray(src.recent_leads)    ? src.recent_leads.slice(0, 8)    : null
} }];
